int cfg_ok = 1;
int sample_valid = 1;
double mnorm = 0.0, tnorm = 0.0;
adcs_vec3_t m, t, crossv;
double dotv, cnorm, angle;
sa_mode_t new_mode;
int rejected = 0;
int absorbed = 0;
double gain;
adcs_vec3_t torque;
adcs_vec3_t limited;
unint32 mask = 0U;
size_t i;
double vals[3];
double prev[3];

/* Validate configuration. */
if ((sa_input.enable != 0) && (sa_input.enable != 1)) cfg_ok = 0;
if ((sa_input.valid != 0) && (sa_input.valid != 1)) cfg_ok = 0;
if (!(sa_config.enter_rad >= 0.0)) cfg_ok = 0;
if (!(sa_config.enter_rad < sa_config.exit_rad)) cfg_ok = 0;
if (!(sa_config.exit_rad <= ADCS_PI)) cfg_ok = 0;
if (!(sa_config.acquire_gain_nm_rad >= 0.0)) cfg_ok = 0;
if (!(sa_config.track_gain_nm_rad >= 0.0)) cfg_ok = 0;
if (!(sa_config.torque_limit_nm > 0.0)) cfg_ok = 0;
if (!(sa_config.max_slew_nm_per_cycle > 0.0)) cfg_ok = 0;
if (!(sa_config.coast_decay >= 0.0) || !(sa_config.coast_decay <= 1.0)) cfg_ok = 0;
if ((sa_config.acquire_samples < 1U) || (sa_config.acquire_samples > 20U)) cfg_ok = 0;
if (!(sa_config.max_coast_samples >= 1U)) cfg_ok = 0;
if (!(sa_config.max_coast_samples < sa_config.max_bad_samples)) cfg_ok = 0;
if (!(sa_config.max_bad_samples <= 20U)) cfg_ok = 0;

/* Disable resets all state and stored torque. */
if (sa_input.enable == 0) {
    sa_state.mode = SA_OFF;
    sa_state.good_samples = 0U;
    sa_state.bad_samples = 0U;
    sa_state.coast_samples = 0U;
    sa_state.previous_torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.mode = SA_OFF;
    sa_output.good_samples = 0U;
    sa_output.bad_samples = 0U;
    sa_output.coast_samples = 0U;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.slew_mask = 0U;
    return;
}

/* Rejected sample checks (configuration, flags, pointers, finiteness). */
if (!cfg_ok) {
    rejected = 1;
} else if ((sa_input.valid != 0) && (sa_input.valid != 1)) {
    rejected = 1;
} else if (sa_input.valid == 0) {
    rejected = 1;
} else if ((sa_input.measured_body == NULL) || (sa_input.target_body == NULL)) {
    rejected = 1;
} else if ((!adcs_is_finite_vec3(sa_input.measured_body)) ||
           (!adcs_is_finite_vec3(sa_input.target_body))) {
    rejected = 1;
} else {
    mnorm = adcs_vec3_norm(sa_input.measured_body);
    tnorm = adcs_vec3_norm(sa_input.target_body);
    if ((mnorm <= ADCS_EPS_NORM) || (tnorm <= ADCS_EPS_NORM)) rejected = 1;
}

if (rejected) {
    sa_state.good_samples = 0U;
    sa_state.bad_samples += 1U;
    if (cfg_ok && ((sa_state.mode == SA_TRACK) || (sa_state.mode == SA_COAST))) {
        if (sa_state.coast_samples < sa_config.max_coast_samples) {
            absorbed = 1;
            sa_state.coast_samples += 1U;
            sa_state.mode = SA_COAST;
        }
    }
} else {
    sa_state.bad_samples = 0U;
    if (sa_state.mode == SA_OFF) sa_state.mode = SA_SEARCH;
}

if (!absorbed) {
    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_state.mode = SA_FAULT;
    }
}

if ((sa_state.mode == SA_FAULT) && (!absorbed)) {
    sa_output.mode = SA_FAULT;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = sa_state.previous_torque_nm;
    sa_output.slew_mask = 0U;
    return;
}

if (absorbed) {
    sa_output.mode = sa_state.mode;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
    sa_output.slew_mask = 0U;
    sa_state.previous_torque_nm = sa_output.torque_nm;
    return;
}

if (rejected) {
    sa_output.mode = sa_state.mode;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = sa_state.previous_torque_nm;
    sa_output.slew_mask = 0U;
    return;
}

/* Accepted: normalize measured/target and compute angle with atan2(norm(cross), dot). */
m = adcs_vec3_scale(sa_input.measured_body, 1.0 / mnorm);
t = adcs_vec3_scale(sa_input.target_body, 1.0 / tnorm);
dotv = adcs_vec3_dot(&m, &t);
crossv = adcs_vec3_cross(&m, &t);
cnorm = adcs_vec3_norm(&crossv);

if (dotv >= 1.0) {
    angle = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
} else if (dotv <= -1.0) {
    double ax = fabs(m.x), ay = fabs(m.y), az = fabs(m.z);
    adcs_vec3_t basis;
    adcs_vec3_t axis;
    if ((ax <= ay) && (ax <= az)) {
        basis = (adcs_vec3_t){1, 0, 0};
    } else if ((ay <= ax) && (ay <= az)) {
        basis = (adcs_vec3_t){0, 1, 0};
    } else {
        basis = (adcs_vec3_t){0, 0, 1};
    }
    axis = adcs_vec3_cross(&m, &basis);
    axis = adcs_vec3_scale(&axis, 1.0 / adcs_vec3_norm(&axis));
    angle = ADCS_PI;
    sa_output.rotation_axis = axis;
} else {
    angle = atan2(cnorm, dotv);
    sa_output.rotation_axis = adcs_vec3_scale(&crossv, 1.0 / cnorm);
}
sa_output.error_rad = angle;

/* Mode transitions. */
if (sa_state.mode == SA_SEARCH) {
    if (angle <= sa_config.enter_rad) {
        sa_state.mode = SA_ACQUIRE;
        sa_state.good_samples = 1U;
    } else {
        sa_state.good_samples = 0U;
    }
} else if (sa_state.mode == SA_ACQUIRE) {
    if (angle <= sa_config.enter_rad) {
        sa_state.good_samples += 1U;
        if (sa_state.good_samples >= sa_config.acquire_samples) {
            sa_state.mode = SA_TRACK;
            sa_state.coast_samples = 0U;
        }
    } else {
        sa_state.mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    }
} else if (sa_state.mode == SA_TRACK) {
    if (angle >= sa_config.exit_rad) {
        sa_state.mode = SA_SEARCH;
    }
} else if (sa_state.mode == SA_COAST) {
    sa_state.coast_samples = 0U;
    if (angle < sa_config.exit_rad) {
        sa_state.mode = SA_TRACK;
    } else {
        sa_state.mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    }
}

new_mode = sa_state.mode;
sa_output.mode = new_mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;

/* Gain selected from the mode after this call's transition. */
if ((new_mode == SA_SEARCH) || (new_mode == SA_ACQUIRE)) {
    gain = sa_config.acquire_gain_nm_rad;
} else {
    gain = sa_config.track_gain_nm_rad;
}

torque = adcs_vec3_scale(&sa_output.rotation_axis, gain);

/* Limit torque magnitude. */
vals[0] = torque.x;
vals[1] = torque.y;
vals[2] = torque.z;
for (i = 0; i < 3U; i++) {
    if (vals[i] > sa_config.torque_limit_nm) vals[i] = sa_config.torque_limit_nm;
    if (vals[i] < -sa_config.torque_limit_nm) vals[i] = -sa_config.torque_limit_nm;
}
torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};

/* Limit every component change from previous published torque by max_slew. */
prev[0] = sa_state.previous_torque_nm.x;
prev[1] = sa_state.previous_torque_nm.y;
prev[2] = sa_state.previous_torque_nm.z;
vals[0] = torque.x;
vals[1] = torque.y;
vals[2] = torque.z;
mask = 0U;
for (i = 0; i < 3U; i++) {
    double d = vals[i] - prev[i];
    if (d > sa_config.max_slew_nm_per_cycle) {
        vals[i] = prev[i] + sa_config.max_slew_nm_per_cycle;
        mask |= (unint32)(1U << i);
    } else if (d < -sa_config.max_slew_nm_per_cycle) {
        vals[i] = prev[i] - sa_config.max_slew_nm_per_cycle;
        mask |= (unint32)(1U << i);
    }
}
limited = (adcs_vec3_t){vals[0], vals[1], vals[2]};

sa_output.torque_nm = limited;
sa_output.slew_mask = mask;
sa_state.previous_torque_nm = limited;

