        sa_state.good_samples = 0U;
        next_mode = SA_SEARCH;
    }
    sa_state.coast_samples = 0U;
} else if (sa_state.mode == SA_ACQUIRE) {
    if (angle <= enter) {
        sa_state.good_samples = sa_state.good_samples + 1U;
        if (sa_state.good_samples >= acq_n) {
            next_mode = SA_TRACK;
        } else {
            next_mode = SA_ACQUIRE;
        }
    } else {
        sa_state.good_samples = 0U;
        next_mode = SA_SEARCH;
    }
    sa_state.coast_samples = 0U;
} else if (sa_state.mode == SA_TRACK) {
    if (angle >= exitv) {
        next_mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    } else {
        next_mode = SA_TRACK;
    }
} else if (sa_state.mode == SA_COAST) {
    sa_state.coast_samples = 0U;
    if (angle < exitv) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
} else if (sa_state.mode == SA_FAULT) {
    next_mode = SA_FAULT;
}
sa_state.mode = next_mode;

if (next_mode == SA_TRACK) {
    tq = gain_trk * angle;
} else if (next_mode == SA_SEARCH || next_mode == SA_ACQUIRE) {
    tq = gain_acq * angle;
} else {
    tq = 0.0;
}

new_torque = adcs_vec3_scale(&axis, tq);

norm_v = adcs_vec3_norm(&new_torque);
if (norm_v > tl && norm_v > 0.0) {
    new_torque = adcs_vec3_scale(&new_torque, tl / norm_v);
}

limited_torque = new_torque;
mask = 0U;
delta_torque.x = new_torque.x - sa_state.previous_torque_nm.x;
delta_torque.y = new_torque.y - sa_state.previous_torque_nm.y;
delta_torque.z = new_torque.z - sa_state.previous_torque_nm.z;
if (delta_torque.x > mslew) {
    limited_torque.x = sa_state.previous_torque_nm.x + mslew;
    mask |= 1U;
} else if (delta_torque.x < -mslew) {
    limited_torque.x = sa_state.previous_torque_nm.x - mslew;
    mask |= 1U;
}
if (delta_torque.y > mslew) {
    limited_torque.y = sa_state.previous_torque_nm.y + mslew;
    mask |= 2U;
} else if (delta_torque.y < -mslew) {
    limited_torque.y = sa_state.previous_torque_nm.y - mslew;
    mask |= 2U;
}
if (delta_torque.z > mslew) {
    limited_torque.z = sa_state.previous_torque_nm.z + mslew;
    mask |= 4U;
} else if (delta_torque.z < -mslew) {
    limited_torque.z = sa_state.previous_torque_nm.z - mslew;
    mask |= 4U;
}
new_torque = limited_torque;
sa_output.slew_mask = mask;

sa_state.previous_torque_nm = new_torque;
sa_output.torque_nm = new_torque;
sa_output.mode = next_mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
return;

candidates.misra:
int config_invalid = 0;
int rejected = 0;
double enter, exitv, gain_acq, gain_trk, tl, mslew, cdecay;
uint32_t acq_n, coast_max, bad_max;
double angle = 0.0;
adcs_vec3_t axis = {0, 0, 0};
adcs_vec3_t meas_n, targ_n;
double dotv, cross_norm, norm_v;
adcs_vec3_t cross_v;
adcs_vec3_t basis;
double bx, by, bz, ax, ay, az;
double tq;
adcs_vec3_t new_torque, delta_torque, limited_torque;
uint32_t mask;
sa_mode_t next_mode;

/* Config validation (always) */
if ((sa_input.enable != 0 && sa_input.enable != 1) ||
    (sa_input.valid != 0 && sa_input.valid != 1)) {
    config_invalid = 1;
}
enter = sa_config.enter_rad;
exitv = sa_config.exit_rad;
gain_acq = sa_config.acquire_gain_nm_rad;
gain_trk = sa_config.track_gain_nm_rad;
tl = sa_config.torque_limit_nm;
mslew = sa_config.max_slew_nm_per_cycle;
cdecay = sa_config.coast_decay;
acq_n = sa_config.acquire_samples;
coast_max = sa_config.max_coast_samples;
bad_max = sa_config.max_bad_samples;

if (!config_invalid) {
    if (!isfinite(enter) || !isfinite(exitv) || !isfinite(gain_acq) ||
        !isfinite(gain_trk) || !isfinite(tl) || !isfinite(mslew) || !isfinite(cdecay)) {
        config_invalid = 1;
    }
}
if (!config_invalid) {
    if (enter < 0.0 || exitv > ADCS_PI || !(enter < exitv)) config_invalid = 1;
    if (gain_acq < 0.0 || gain_trk < 0.0) config_invalid = 1;
    if (tl <= 0.0 || mslew <= 0.0) config_invalid = 1;
    if (cdecay < 0.0 || cdecay > 1.0) config_invalid = 1;
    if (acq_n < 1U || acq_n > 20U) config_invalid = 1;
    if (coast_max < 1U || bad_max > 20U || !(coast_max < bad_max)) config_invalid = 1;
}

/* Rejected-sample determination */
if (config_invalid) {
    rejected = 1;
}
if (!rejected && sa_input.valid == 0U) rejected = 1;
if (!rejected && (sa_input.measured_body == NULL || sa_input.target_body == NULL)) rejected = 1;
if (!rejected && (!adcs_is_finite_vec3(sa_input.measured_body) ||
                  !adcs_is_finite_vec3(sa_input.target_body))) rejected = 1;
if (!rejected) {
    double n1 = adcs_vec3_norm(sa_input.measured_body);
    double n2 = adcs_vec3_norm(sa_input.target_body);
    if (n1 <= ADCS_EPS_NORM || n2 <= ADCS_EPS_NORM) rejected = 1;
}

/* Disable resets everything */
if (sa_input.enable == 0) {
    sa_state.mode = SA_OFF;
    sa_state.good_samples = 0U;
    sa_state.bad_samples = 0U;
    sa_state.coast_samples = 0U;
    sa_state.previous_torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.mode = SA_OFF;
    sa_output.good_samples = 0U;
    sa_output.bad_samples = 0U;
    sa_output.coast_samples = 0U;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.slew_mask = 0U;
    return;
}

if (rejected) {
    sa_state.good_samples = 0U;
    sa_state.bad_samples = sa_state.bad_samples + 1U;

    if (sa_state.mode == SA_TRACK || sa_state.mode == SA_COAST) {
        int absorbed = 0;
        if (!config_invalid && sa_state.coast_samples < coast_max) {
            absorbed = 1;
        }
        if (absorbed) {
            sa_state.coast_samples = sa_state.coast_samples + 1U;
            sa_state.mode = SA_COAST;
            new_torque = adcs_vec3_scale(&sa_state.previous_torque_nm, cdecay);
            sa_state.previous_torque_nm = new_torque;
            sa_output.mode = SA_COAST;
            sa_output.good_samples = sa_state.good_samples;
            sa_output.bad_samples = sa_state.bad_samples;
            sa_output.coast_samples = sa_state.coast_samples;
            sa_output.torque_nm = new_torque;
            sa_output.slew_mask = 0U;
            return;
        }
        /* not absorbed: keep current mode until bad reaches max */
    }

    if (sa_state.bad_samples >= bad_max) {
        sa_state.mode = SA_FAULT;
    }
    sa_output.mode = sa_state.mode;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.torque_nm = sa_state.previous_torque_nm;
    sa_output.slew_mask = 0U;
    return;
}

/* Accepted */
sa_state.bad_samples = 0U;

(void)adcs_vec3_normalize(sa_input.measured_body, 0.0, &meas_n);
(void)adcs_vec3_normalize(sa_input.target_body, 0.0, &targ_n);

dotv = adcs_vec3_dot(&meas_n, &targ_n);
cross_v = adcs_vec3_cross(&meas_n, &targ_n);
cross_norm = adcs_vec3_norm(&cross_v);
if (dotv > 1.0) dotv = 1.0;
if (dotv < -1.0) dotv = -1.0;
angle = atan2(cross_norm, dotv);

if (cross_norm > ADCS_EPS_NORM) {
    axis = adcs_vec3_scale(&cross_v, 1.0 / cross_norm);
} else if (dotv < 0.0) {
    /* Antiparallel: deterministic pi command */
    ax = fabs(meas_n.x);
    ay = fabs(meas_n.y);
    az = fabs(meas_n.z);
    if (ax <= ay && ax <= az) {
        basis = (adcs_vec3_t){1, 0, 0};
    } else if (ay <= az) {
        basis = (adcs_vec3_t){0, 1, 0};
    } else {
        basis = (adcs_vec3_t){0, 0, 1};
    }
    cross_v = adcs_vec3_cross(&meas_n, &basis);
    cross_norm = adcs_vec3_norm(&cross_v);
    if (cross_norm > ADCS_EPS_NORM) {
        axis = adcs_vec3_scale(&cross_v, 1.0 / cross_norm);
    } else {
        axis = (adcs_vec3_t){0, 0, 0};
    }
    angle = ADCS_PI;
} else {
    axis = (adcs_vec3_t){0, 0, 0};
    angle = 0.0;
}
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;

/* State transitions on accepted sample */
next_mode = sa_state.mode;
if (sa_state.mode == SA_OFF || sa_state.mode == SA_SEARCH) {
    if (angle <= enter) {
        sa_state.good_samples = 1U;
        next_mode = SA_ACQUIRE;
    } else {
        sa_state.good_samples = 0U;
        next_mode = SA_SEARCH;
    }
    sa_state.coast_samples = 0U;
} else if (sa_state.mode == SA_ACQUIRE) {
    if (angle <= enter) {
        sa_state.good_samples = sa_state.good_samples + 1U;
        if (sa_state.good_samples >= acq_n) {
            next_mode = SA_TRACK;
        } else {
            next_mode = SA_ACQUIRE;
        }
    } else {
        sa_state.good_samples = 0U;
        next_mode = SA_SEARCH;
    }
    sa_state.coast_samples = 0U;
} else if (sa_state.mode == SA_TRACK) {
    if (angle >= exitv) {
        next_mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    } else {
        next_mode = SA_TRACK;
    }
} else if (sa_state.mode == SA_COAST) {
    sa_state.coast_samples = 0U;
    if (angle < exitv) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
} else {
    /* Fault, or any corrupted/illegal mode: deterministic safety fallback */
    next_mode = SA_FAULT;
}
sa_state.mode = next_mode;

if (next_mode == SA_TRACK) {
    tq = gain_trk * angle;
} else if (next_mode == SA_SEARCH || next_mode == SA_ACQUIRE) {
    tq = gain_acq * angle;
} else {
    tq = 0.0;
}

new_torque = adcs_vec3_scale(&axis, tq);

norm_v = adcs_vec3_norm(&new_torque);
if (norm_v > tl && norm_v > 0.0) {
    new_torque = adcs_vec3_scale(&new_torque, tl / norm_v);
}

limited_torque = new_torque;
mask = 0U;
delta_torque.x = new_torque.x - sa_state.previous_torque_nm.x;
delta_torque.y = new_torque.y - sa_state.previous_torque_nm.y;
delta_torque.z = new_torque.z - sa_state.previous_torque_nm.z;
if (delta_torque.x > mslew) {
    limited_torque.x = sa_state.previous_torque_nm.x + mslew;
    mask |= 1U;
} else if (delta_torque.x < -mslew) {
    limited_torque.x = sa_state.previous_torque_nm.x - mslew;
    mask |= 1U;
} else {
    /* within slew: no change */
}
if (delta_torque.y > mslew) {
    limited_torque.y = sa_state.previous_torque_nm.y + mslew;
    mask |= 2U;
} else if (delta_torque.y < -mslew) {
    limited_torque.y = sa_state.previous_torque_nm.y - mslew;
    mask |= 2U;
} else {
    /* within slew: no change */
}
if (delta_torque.z > mslew) {
    limited_torque.z = sa_state.previous_torque_nm.z + mslew;
    mask |= 4U;
} else if (delta_torque.z < -mslew) {
    limited_torque.z = sa_state.previous_torque_nm.z - mslew;
    mask |= 4U;
} else {
    /* within slew: no change */
}
new_torque = limited_torque;
sa_output.slew_mask = mask;

sa_state.previous_torque_nm = new_torque;
sa_output.torque_nm = new_torque;
sa_output.mode = next_mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
return;

candidates.raw:
{
    sa_mode_t prev_mode;
    sa_mode_t new_mode;
    double gain;
    adcs_vec3_t meas_n, targ_n, cross_nt, axis;
    adcs_vec3_t torque, prev_t, delta;
    double dotv, normc, angle;
    double mnorm, tnorm;
    int config_ok;
    int sample_ok;
    unint32 i;
    adcs_vec3_t basis[3];
    double bcomp[3];
    unint32 chosen;
    double bmin;
    adcs_vec3_t new_t;

    /* ---- config validation ---- */
    config_ok = 1;
    if ((sa_input.enable != 0) && (sa_input.enable != 1)) config_ok = 0;
    if ((sa_input.valid != 0) && (sa_input.valid != 1)) config_ok = 0;
    if (!(sa_config.enter_rad >= 0.0 && sa_config.enter_rad < sa_config.exit_rad &&
          sa_config.exit_rad <= ADCS_PI)) config_ok = 0;
    if (!(sa_config.acquire_gain_nm_rad >= 0.0) || (!(sa_config.track_gain_nm_rad >= 0.0))) config_ok = 0;
    if (!(sa_config.torque_limit_nm > 0.0) || (!(sa_config.max_slew_nm_per_cycle > 0.0))) config_ok = 0;
    if (!(sa_config.coast_decay >= 0.0 && sa_config.coast_decay <= 1.0)) config_ok = 0;
    if (!(sa_config.acquire_samples >= 1U && sa_config.acquire_samples <= 20U)) config_ok = 0;
    if (!(sa_config.max_coast_samples >= 1U && sa_config.max_coast_samples < sa_config.max_bad_samples &&
          sa_config.max_bad_samples <= 20U)) config_ok = 0;

    prev_mode = sa_state.mode;

    /* ---- sample validity ---- */
    sample_ok = 1;
    if (!config_ok) sample_ok = 0;
    if (sa_input.valid == 0) sample_ok = 0;
    if (sa_input.measured_body == NULL || sa_input.target_body == NULL) sample_ok = 0;
    else {
        if (!adcs_is_finite_vec3(sa_input.measured_body)) sample_ok = 0;
        if (!adcs_is_finite_vec3(sa_input.target_body)) sample_ok = 0;
        mnorm = adcs_vec3_norm(sa_input.measured_body);
        tnorm = adcs_vec3_norm(sa_input.target_body);
        if (!(mnorm > ADCS_EPS_NORM)) sample_ok = 0;
        if (!(tnorm > ADCS_EPS_NORM)) sample_ok = 0;
    }

    if (!sample_ok) {
        /* rejected sample */
        sa_state.good_samples = 0U;
        sa_state.bad_samples += 1U;
        if ((prev_mode == SA_TRACK || prev_mode == SA_COAST) && config_ok &&
            sa_state.coast_samples < sa_config.max_coast_samples) {
            sa_state.mode = SA_COAST;
            sa_state.coast_samples += 1U;
            sa_state.previous_torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
        } else if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_state.mode = SA_FAULT;
        }
        sa_output.mode = sa_state.mode;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
        sa_output.torque_nm = sa_state.previous_torque_nm;
        sa_output.slew_mask = 0U;
        return;
    }

    /* ---- accepted sample ---- */
    sa_state.bad_samples = 0U;
    if (prev_mode == SA_COAST) sa_state.coast_samples = 0U;

    adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &meas_n);
    adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &targ_n);

    dotv = adcs_vec3_dot(&meas_n, &targ_n);
    cross_nt = adcs_vec3_cross(&meas_n, &targ_n);
    normc = adcs_vec3_norm(&cross_nt);
    angle = atan2(normc, dotv);

    if (normc > ADCS_EPS_COLLINEAR) {
        axis = adcs_vec3_scale(&cross_nt, 1.0 / normc);
    } else {
        basis[0] = (adcs_vec3_t){1, 0, 0};
        basis[1] = (adcs_vec3_t){0, 1, 0};
        basis[2] = (adcs_vec3_t){0, 0, 1};
        bcomp[0] = fabs(meas_n.x);
        bcomp[1] = fabs(meas_n.y);
        bcomp[2] = fabs(meas_n.z);
        chosen = 0U;
        bmin = bcomp[0];
        if (bcomp[1] < bmin) { bmin = bcomp[1]; chosen = 1U; }
        if (bcomp[2] < bmin) { bmin = bcomp[2]; chosen = 2U; }
        cross_nt = adcs_vec3_cross(&meas_n, &basis[chosen]);
        adcs_vec3_normalize(&cross_nt, ADCS_EPS_NORM, &axis);
    }

    /* ---- transitions ---- */
    new_mode = prev_mode;
    if (prev_mode == SA_OFF) new_mode = SA_SEARCH;

    if (new_mode == SA_SEARCH) {
        if (angle <= sa_config.enter_rad) {
            new_mode = SA_ACQUIRE;
            sa_state.good_samples = 0U;
        }
    } else if (new_mode == SA_ACQUIRE) {
        if (angle <= sa_config.enter_rad) {
            sa_state.good_samples += 1U;
            if (sa_state.good_samples >= sa_config.acquire_samples) {
                new_mode = SA_TRACK;
                sa_state.good_samples = 0U;
            }
        } else {
            new_mode = SA_SEARCH;
            sa_state.good_samples = 0U;
        }
    } else if (new_mode == SA_TRACK) {
        if (angle >= sa_config.exit_rad) {
            new_mode = SA_SEARCH;
            sa_state.good_samples = 0U;
        }
    } else if (new_mode == SA_COAST) {
        if (angle < sa_config.exit_rad) new_mode = SA_TRACK;
        else new_mode = SA_SEARCH;
    }

    /* ---- gain from post-transition mode ---- */
    gain = (new_mode == SA_TRACK) ? sa_config.track_gain_nm_rad : sa_config.acquire_gain_nm_rad;

    torque = adcs_vec3_scale(&axis, -gain * angle);

    /* limit magnitude */
    {
        double tn = adcs_vec3_norm(&torque);
        if (tn > sa_config.torque_limit_nm) {
            torque = adcs_vec3_scale(&torque, sa_config.torque_limit_nm / tn);
        }
    }

    /* limit slew vs previous published torque */
    prev_t = sa_state.previous_torque_nm;
    delta = adcs_vec3_sub(&torque, &prev_t);
    {
        double d[3];
        unint32 mask = 0U;
        d[0] = delta.x; d[1] = delta.y; d[2] = delta.z;
        for (i = 0U; i < 3U; i++) {
            if (d[i] > sa_config.max_slew_nm_per_cycle) {
                d[i] = sa_config.max_slew_nm_per_cycle;
                mask |= (unint32)(1U << i);
            } else if (d[i] < -sa_config.max_slew_nm_per_cycle) {
                d[i] = -sa_config.max_slew_nm_per_cycle;
                mask |= (unint32)(1U << i);
            }
        }
        torque.x = prev_t.x + d[0];
        torque.y = prev_t.y + d[1];
        torque.z = prev_t.z + d[2];
        new_t = torque;
        sa_output.slew_mask = mask;
    }

    sa_state.mode = new_mode;
    sa_state.previous_torque_nm = new_t;

    sa_output.mode = new_mode;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.error_rad = angle;
    sa_output.rotation_axis = axis;
    sa_output.torque_nm = new_t;
}

